/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var format = require( '@stdlib/string/format' );
var stdout = require( './stdout' );


// MAIN //

/**
* Plot view constructor.
*
* @private
* @constructor
* @param {Object} plot - plot instance
* @param {Function} plot.render - method for rendering a plot instance
* @returns {View} view instance
*/
function View( plot ) {
	if ( !( this instanceof View ) ) {
		return new View( plot );
	}
	setNonEnumerableReadOnly( this, '_plot', plot );
	return this;
}

/**
* Renders a plot view.
*
* @name render
* @memberof View.prototype
* @type {Function}
* @param {string} viewer - viewer
* @throws {Error} must provide a supported viewer
*/
setNonEnumerableReadOnly( View.prototype, 'render', function render( viewer ) {
	if ( viewer === 'stdout' ) {
		return stdout( this._plot );
	}
	throw new Error( format( 'invalid argument. Must provide a supported viewer. Value: `%s`.', viewer ) );
});


// EXPORTS //

module.exports = View;
